def transform(grid):
    out=[row[:] for row in grid]
    pts=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==2]
    from collections import Counter
    rc=Counter(r for r,c in pts); cc=Counter(c for r,c in pts)
    if max(rc.values())>=max(cc.values()):
        axis=max((r for r,n in rc.items() if n==max(rc.values())))
        lo=min(c for r,c in pts if r==axis); hi=max(c for r,c in pts if r==axis)
        for c in range(lo,hi+1):
            if out[axis][c]==0: out[axis][c]=3
        for r,c in pts:
            for y in range(min(r,axis),max(r,axis)+1):
                if out[y][c]==0: out[y][c]=3
    else:
        axis=min(c for c,n in cc.items() if n==max(cc.values()))
        lo=min(r for r,c in pts if c==axis); hi=max(r for r,c in pts if c==axis)
        for r in range(lo,hi+1):
            if out[r][axis]==0: out[r][axis]=3
        for r,c in pts:
            for x in range(min(c,axis),max(c,axis)+1):
                if out[r][x]==0: out[r][x]=3
    return out
